-- HAC-40 fleet resource commands. Structural only, no synthetic production rows.
create table public.cargo_capability_definitions (
 id uuid primary key default gen_random_uuid(), carrier_id uuid not null references public.carriers(id),
 carrier_service_id uuid not null references public.carrier_services(id), cargo_category_id uuid not null references public.cargo_categories(id),
 requirements jsonb not null check(jsonb_typeof(requirements)='array'), max_weight_kg numeric check(max_weight_kg>0),
 temperature_range jsonb, certifications jsonb not null check(jsonb_typeof(certifications)='array'),
 evidence text,verified_at timestamptz,valid_until timestamptz,active boolean not null,
 version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(valid_until is null or verified_at is null or valid_until>verified_at));
alter table public.cargo_capability_definitions add constraint fleet_definition_scope unique(id,carrier_id,carrier_service_id);
alter table public.cargo_capability_definitions enable row level security;
revoke all on public.cargo_capability_definitions from public,anon,authenticated,service_role;
grant select(id,requirements,max_weight_kg,active) on public.cargo_capability_definitions to authenticated;
create policy capability_definition_evaluator_select on public.cargo_capability_definitions for select to authenticated using((select private.has_any_organization()));
alter table public.carrier_depots add constraint fleet_depot_carrier_unique unique(id,carrier_id);
alter table public.transport_assets drop constraint transport_assets_mode_check;
alter table public.transport_assets add constraint fleet_asset_mode check(mode in ('ROAD','RAIL','SEA','AIR')),
 add column operating_status text not null default 'AVAILABLE' check(operating_status in ('AVAILABLE','IN_SERVICE','MAINTENANCE','OUT_OF_SERVICE')),
 add column home_depot_id uuid, add column fulfilment_source text not null default 'OWN' check(fulfilment_source in ('OWN','CONTRACTED','PARTNER')),
 add column fulfilment_partner_id uuid references public.fulfilment_partners(id), add column evidence text,
 add column registration_code text, add column registered_at date, add column brand text, add column model text,
 add column variant text, add column body_type text, add column usable_dimensions jsonb,
 add column gross_weight_limit_kg numeric check(gross_weight_limit_kg>0), add column odometer_km numeric check(odometer_km>=0),
 add column condition_reason text, add column version integer not null default 1 check(version>0),
 add constraint fleet_home_depot foreign key(home_depot_id,carrier_id) references public.carrier_depots(id,carrier_id),
 add constraint fleet_useful_gross check(max_weight_kg is null or gross_weight_limit_kg is null or max_weight_kg<=gross_weight_limit_kg);
alter table public.transport_assets add constraint fleet_asset_scope unique(id,carrier_id,carrier_service_id);
create unique index fleet_asset_plate_unique on public.transport_assets(carrier_id,plate) where plate is not null and mode='ROAD';
alter table public.capacity_pools add column mode text check(mode in ('ROAD','RAIL','SEA','AIR')),
 add column starts_at timestamptz, add column ends_at timestamptz,
 add column fulfilment_source text check(fulfilment_source in ('OWN','CONTRACTED','PARTNER')),
 add column fulfilment_partner_id uuid references public.fulfilment_partners(id), add column evidence text,
 add column version integer not null default 1 check(version>0),
 add constraint fleet_pool_window check((starts_at is null and ends_at is null) or ends_at>starts_at);
alter table public.capacity_calendars add column carrier_id uuid references public.carriers(id),
 add column created_at timestamptz not null default now(), add column timezone text,
 add column horizon_starts_at timestamptz, add column horizon_ends_at timestamptz,
 add column source text, add column last_verified_at timestamptz, add column freshness text,
 add constraint fleet_calendar_horizon check((horizon_starts_at is null and horizon_ends_at is null) or horizon_ends_at>horizon_starts_at);
alter table public.scheduled_maintenances add column carrier_id uuid references public.carriers(id),
 add column carrier_service_id uuid references public.carrier_services(id), add column kind text,
 add column status text not null default 'SCHEDULED' check(status in ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')),
 add column source text, add column version integer not null default 1 check(version>0), add column updated_at timestamptz not null default now();
alter table public.repositioning_blocks add column carrier_id uuid references public.carriers(id),
 add column carrier_service_id uuid references public.carrier_services(id), add column origin jsonb, add column next_pickup jsonb,
 add column estimated_travel_seconds integer check(estimated_travel_seconds>0),
 add column status text not null default 'PLANNED' check(status in ('PLANNED','IN_PROGRESS','COMPLETED','CANCELLED')),
 add column source text, add column version integer not null default 1 check(version>0), add column updated_at timestamptz not null default now();
alter table public.asset_cargo_capabilities add column id uuid not null default gen_random_uuid() unique,
 add column definition_id uuid references public.cargo_capability_definitions(id),
 add column carrier_id uuid references public.carriers(id), add column carrier_service_id uuid references public.carrier_services(id),
 add column evidence text, add column verified_at timestamptz, add column valid_until timestamptz, add column active boolean not null default true,
 add column version integer not null default 1 check(version>0), add column created_at timestamptz not null default now(), add column updated_at timestamptz not null default now();
-- Existing baseline rows keep unknown additional attributes; do not fabricate provenance or dates.
update public.transport_assets set operating_status='OUT_OF_SERVICE' where not active;
update public.capacity_calendars c set carrier_id=s.carrier_id from public.carrier_services s where c.carrier_service_id=s.id;
update public.scheduled_maintenances m set carrier_id=a.carrier_id,carrier_service_id=a.carrier_service_id from public.transport_assets a where m.transport_asset_id=a.id;
update public.repositioning_blocks b set carrier_id=c.carrier_id,carrier_service_id=c.carrier_service_id from public.capacity_calendars c where b.capacity_calendar_id=c.id;
update public.asset_cargo_capabilities c set carrier_id=a.carrier_id,carrier_service_id=a.carrier_service_id from public.transport_assets a where c.transport_asset_id=a.id;
alter table public.asset_cargo_capabilities add constraint fleet_definition_asset_scope foreign key(definition_id,carrier_id,carrier_service_id) references public.cargo_capability_definitions(id,carrier_id,carrier_service_id);
create index fleet_definition_service_idx on public.cargo_capability_definitions(carrier_service_id);
create index fleet_capability_definition_idx on public.asset_cargo_capabilities(definition_id);
create index fleet_asset_home_depot_idx on public.transport_assets(home_depot_id);
create index fleet_asset_partner_idx on public.transport_assets(fulfilment_partner_id);
create index fleet_pool_partner_idx on public.capacity_pools(fulfilment_partner_id);
create function private.guard_v2_service_fleet_mode() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.transport_mode is distinct from old.transport_mode and (
  exists(select 1 from public.transport_assets where carrier_service_id=old.id and mode<>new.transport_mode)
  or exists(select 1 from public.capacity_pools where carrier_service_id=old.id and mode is not null and mode<>new.transport_mode)) then
  raise exception 'FLEET_SERVICE_MODE_MISMATCH' using errcode='PT400';end if;
 return new;end;$$;
revoke all on function private.guard_v2_service_fleet_mode() from public,anon,authenticated,service_role;
create trigger v2_service_fleet_mode_guard before update on public.carrier_services for each row execute function private.guard_v2_service_fleet_mode();
create index cargo_capability_definitions_fleet_carrier_idx on public.cargo_capability_definitions(carrier_id,created_at,id);
alter table public.cargo_capability_definitions add column fleet_managed boolean not null default false;
create index transport_assets_fleet_carrier_idx on public.transport_assets(carrier_id,created_at,id);
alter table public.transport_assets add column fleet_managed boolean not null default false;
create index capacity_pools_fleet_carrier_idx on public.capacity_pools(carrier_id,created_at,id);
alter table public.capacity_pools add column fleet_managed boolean not null default false;
create index capacity_calendars_fleet_carrier_idx on public.capacity_calendars(carrier_id,created_at,id);
alter table public.capacity_calendars add column fleet_managed boolean not null default false;
create index scheduled_maintenances_fleet_carrier_idx on public.scheduled_maintenances(carrier_id,created_at,id);
alter table public.scheduled_maintenances add column fleet_managed boolean not null default false;
create index repositioning_blocks_fleet_carrier_idx on public.repositioning_blocks(carrier_id,created_at,id);
alter table public.repositioning_blocks add column fleet_managed boolean not null default false;
create index asset_cargo_capabilities_fleet_carrier_idx on public.asset_cargo_capabilities(carrier_id,created_at,id);
alter table public.asset_cargo_capabilities add column fleet_managed boolean not null default false;
create function private.guard_v2_fleet() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if current_user<>'postgres' then raise exception 'DIRECT_FLEET_MUTATION_FORBIDDEN' using errcode='PT403';end if;
 if TG_OP='DELETE' then return old;end if;
 if TG_TABLE_NAME in ('scheduled_maintenances','asset_cargo_capabilities') then
  select carrier_id,carrier_service_id into new.carrier_id,new.carrier_service_id from public.transport_assets where id=new.transport_asset_id;
 elsif TG_TABLE_NAME='repositioning_blocks' then
  select carrier_id,carrier_service_id into new.carrier_id,new.carrier_service_id from public.capacity_calendars where id=new.capacity_calendar_id;
 elsif TG_TABLE_NAME='capacity_calendars' then
  select carrier_id into new.carrier_id from public.carrier_services where id=new.carrier_service_id;
 end if;
 if new.carrier_id is null or new.carrier_service_id is null then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
 if TG_OP='UPDATE' then
  if (new.id,new.carrier_id,new.carrier_service_id) is distinct from (old.id,old.carrier_id,old.carrier_service_id) then raise exception 'IMMUTABLE_FLEET_IDENTITY' using errcode='PT400';end if;
  if old.fleet_managed and not new.fleet_managed then raise exception 'IMMUTABLE_MANAGEMENT' using errcode='PT400';end if;
  new.version:=old.version+1;new.updated_at:=now();
 end if;return new;end;$$;
revoke all on function private.guard_v2_fleet() from public,anon,authenticated,service_role;
create trigger v2_fleet_command_guard before insert or update or delete on public.cargo_capability_definitions for each row execute function private.guard_v2_fleet();
alter table public.cargo_capability_definitions alter column carrier_id set not null, add constraint cargo_capability_definitions_fleet_service foreign key(carrier_service_id,carrier_id) references public.carrier_services(id,carrier_id);
create trigger v2_fleet_command_guard before insert or update or delete on public.transport_assets for each row execute function private.guard_v2_fleet();
