create trigger v2_fleet_command_guard before insert or update or delete on public.capacity_pools for each row execute function private.guard_v2_fleet();
alter table public.capacity_pools alter column carrier_id set not null, add constraint capacity_pools_fleet_service foreign key(carrier_service_id,carrier_id) references public.carrier_services(id,carrier_id);
create trigger v2_fleet_command_guard before insert or update or delete on public.capacity_calendars for each row execute function private.guard_v2_fleet();
alter table public.capacity_calendars alter column carrier_id set not null, add constraint capacity_calendars_fleet_service foreign key(carrier_service_id,carrier_id) references public.carrier_services(id,carrier_id);
create trigger v2_fleet_command_guard before insert or update or delete on public.scheduled_maintenances for each row execute function private.guard_v2_fleet();
alter table public.scheduled_maintenances alter column carrier_id set not null, add constraint scheduled_maintenances_fleet_service foreign key(carrier_service_id,carrier_id) references public.carrier_services(id,carrier_id);
