alter table public.asset_cargo_capabilities alter column carrier_id set not null, add constraint asset_cargo_capabilities_fleet_service foreign key(carrier_service_id,carrier_id) references public.carrier_services(id,carrier_id);
grant select(status) on public.scheduled_maintenances,public.repositioning_blocks to authenticated;
