create function private.fleet_record(p_kind text,p_id uuid) returns jsonb language plpgsql set search_path='' as $$
declare result jsonb;begin case p_kind
when 'capability-definitions' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'categoryId',r.cargo_category_id,'requirements',r.requirements,'maxWeightKg',r.max_weight_kg,'temperatureRange',r.temperature_range,'certifications',r.certifications,'evidence',r.evidence,'verifiedAt',r.verified_at,'validUntil',r.valid_until,'active',r.active)) into result from public.cargo_capability_definitions r where r.id=p_id;
when 'assets' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'code',r.code,'mode',r.mode,'equipmentType',r.equipment_code,'role',case when r.asset_role='CARRIER' then 'LOAD_BEARING' else 'AUXILIARY' end,'usefulCapacityKg',r.max_weight_kg,'usableVolumeM3',r.max_volume_m3,'operatingStatus',r.operating_status,'homeDepotId',r.home_depot_id,'provenance',r.fulfilment_source,'partnerId',r.fulfilment_partner_id,'evidence',r.evidence,'roadVehicle',case when r.mode='ROAD' then jsonb_build_object('plate',r.plate,'registrationCode',r.registration_code,'registeredAt',r.registered_at,'brand',r.brand,'model',r.model,'variant',r.variant,'bodyType',r.body_type,'usableDimensions',r.usable_dimensions,'grossWeightLimitKg',r.gross_weight_limit_kg,'odometerKm',r.odometer_km,'conditionReason',r.condition_reason,'axleConfig',r.axle_config) else null end)) into result from public.transport_assets r where r.id=p_id;
when 'capacity-pools' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'code',r.code,'mode',r.mode,'equipmentType',r.equipment_code,'serviceWindow',case when r.starts_at is null then null else jsonb_build_object('startsAt',r.starts_at,'endsAt',r.ends_at) end,'declaredCapacity',jsonb_build_object('weightKg',r.max_weight_kg,'volumeM3',r.max_volume_m3),'provenance',r.fulfilment_source,'partnerId',r.fulfilment_partner_id,'evidence',r.evidence,'supportedCargoCategoryIds',r.supported_cargo_category_ids,'active',r.active)) into result from public.capacity_pools r where r.id=p_id;
when 'calendars' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'assetId',r.transport_asset_id,'capacityPoolId',r.capacity_pool_id,'timezone',r.timezone,'horizon',case when r.horizon_starts_at is null then null else jsonb_build_object('startsAt',r.horizon_starts_at,'endsAt',r.horizon_ends_at) end,'source',r.source,'lastVerifiedAt',r.last_verified_at,'freshness',r.freshness,'validUntil',r.valid_until,'complete',r.complete,'availableWindows',r.available_windows,'readyPickupAreaId',r.ready_pickup_area_id)) into result from public.capacity_calendars r where r.id=p_id;
when 'maintenances' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'assetId',r.transport_asset_id,'blockedWindow',jsonb_build_object('startsAt',r.starts_at,'endsAt',r.ends_at),'kind',r.kind,'status',r.status,'source',r.source,'reason',r.reason)) into result from public.scheduled_maintenances r where r.id=p_id;
when 'repositioning-blocks' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'calendarId',r.capacity_calendar_id,'occupiedWindow',jsonb_build_object('startsAt',r.starts_at,'endsAt',r.ends_at),'origin',r.origin,'nextPickup',r.next_pickup,'estimatedTravelSeconds',r.estimated_travel_seconds,'status',r.status,'source',r.source,'reason',r.reason)) into result from public.repositioning_blocks r where r.id=p_id;
when 'asset-capabilities' then select jsonb_build_object('id',r.id,'organizationId',null,'carrierId',r.carrier_id,'serviceId',r.carrier_service_id,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at,'value',jsonb_build_object('schemaVersion','2.0','serviceId',r.carrier_service_id,'assetId',r.transport_asset_id,'categoryId',r.cargo_category_id,'temperatureRange',case when r.temperature_min_c is null then null else jsonb_build_object('minCelsius',r.temperature_min_c,'maxCelsius',r.temperature_max_c) end,'certifications',r.certifications,'evidence',r.evidence,'verifiedAt',r.verified_at,'validUntil',r.valid_until,'active',r.active,'definitionId',r.definition_id)) into result from public.asset_cargo_capabilities r where r.id=p_id;
else raise exception 'INVALID_FLEET_KIND' using errcode='PT400';end case;return result;end;$$;
create function private.fleet_target(p_kind text) returns text language plpgsql immutable set search_path='' as $$begin case p_kind
when 'capability-definitions' then return 'cargo_capability_definitions';
when 'assets' then return 'transport_assets';
when 'capacity-pools' then return 'capacity_pools';
when 'calendars' then return 'capacity_calendars';
when 'maintenances' then return 'scheduled_maintenances';
when 'repositioning-blocks' then return 'repositioning_blocks';
when 'asset-capabilities' then return 'asset_cargo_capabilities';
else raise exception 'INVALID_FLEET_KIND' using errcode='PT400';end case;end;$$;
create function private.read_v2_fleet(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_limit integer,p_offset integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare t text; r record; result jsonb:='[]';begin
 if p_service_id is not null or p_carrier_id is null then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 -- Fleet operational data is not the public discovery catalog. Require a live editor/admin grant on every read/replay.
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'services',p_carrier_id,null,true,null);
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset not between 0 and 100000 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 t:=private.fleet_target(p_kind);
 for r in execute format('select id from public.%I where carrier_id=$1 and ($2 is null or id=$2) order by created_at,id limit $3 offset $4',t)
 using p_carrier_id,p_id,p_limit,p_offset loop result:=result||jsonb_build_array(private.fleet_record(p_kind,r.id));end loop;
 return result;end;$$;
create function private.command_v2_fleet(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,p_service_id uuid,p_id uuid,p_idempotency_key uuid,p_expected_version integer,p_value jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare t text; s json; h text; receipt private.v2_catalog_receipts%rowtype; current_version integer; saved_id uuid;
 sid uuid; parent_id uuid; cal_id uuid; w jsonb; other_w jsonb; start_at timestamptz; end_at timestamptz; result jsonb; previous jsonb;begin
 if p_service_id is not null or p_carrier_id is null then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'services',p_carrier_id,null,true,null);
 if p_idempotency_key is null or ((p_id is null) is distinct from (p_expected_version is null)) or p_expected_version<1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 t:=private.fleet_target(p_kind);case p_kind
when 'capability-definitions' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"categoryId":{"type":"string","format":"uuid"},"requirements":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"maxWeightKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"temperatureRange":{"anyOf":[{"type":"object","properties":{"minCelsius":{"type":"number"},"maxCelsius":{"type":"number"}},"required":["minCelsius","maxCelsius"],"additionalProperties":false},{"type":"null"}]},"certifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"verifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","categoryId","requirements","maxWeightKg","temperatureRange","certifications","evidence","verifiedAt","validUntil","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'assets' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"mode":{"type":"string","enum":["ROAD","RAIL","SEA","AIR"]},"equipmentType":{"type":"string","enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},"role":{"type":"string","enum":["LOAD_BEARING","AUXILIARY"]},"usefulCapacityKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"usableVolumeM3":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"operatingStatus":{"type":"string","enum":["AVAILABLE","IN_SERVICE","MAINTENANCE","OUT_OF_SERVICE"]},"homeDepotId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"provenance":{"type":"string","enum":["OWN","CONTRACTED","PARTNER"]},"partnerId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"roadVehicle":{"anyOf":[{"type":"object","properties":{"plate":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"registrationCode":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"registeredAt":{"anyOf":[{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$"},{"type":"null"}]},"brand":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"model":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"variant":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"bodyType":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"usableDimensions":{"anyOf":[{"type":"object","properties":{"length":{"type":"number","exclusiveMinimum":0},"width":{"type":"number","exclusiveMinimum":0},"height":{"type":"number","exclusiveMinimum":0}},"required":["length","width","height"],"additionalProperties":false},{"type":"null"}]},"grossWeightLimitKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"odometerKm":{"anyOf":[{"type":"number","minimum":0},{"type":"null"}]},"conditionReason":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"axleConfig":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]}},"required":["plate","registrationCode","registeredAt","brand","model","variant","bodyType","usableDimensions","grossWeightLimitKg","odometerKm","conditionReason","axleConfig"],"additionalProperties":false},{"type":"null"}]}},"required":["schemaVersion","serviceId","code","mode","equipmentType","role","usefulCapacityKg","usableVolumeM3","operatingStatus","homeDepotId","provenance","partnerId","evidence","roadVehicle"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'capacity-pools' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"code":{"type":"string","pattern":"^[A-Z][A-Z0-9_]{0,99}$"},"mode":{"type":"string","enum":["ROAD","RAIL","SEA","AIR"]},"equipmentType":{"anyOf":[{"type":"string","enum":["BOX_TRUCK","REEFER_TRUCK","FLATBED","TANKER_TRUCK","TRACTOR_TRAILER","ISO_CONTAINER","RAIL_WAGON","AIR_ULD"]},{"type":"null"}]},"serviceWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"declaredCapacity":{"type":"object","properties":{"weightKg":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]},"volumeM3":{"anyOf":[{"type":"number","exclusiveMinimum":0},{"type":"null"}]}},"required":["weightKg","volumeM3"],"additionalProperties":false},"provenance":{"type":"string","enum":["OWN","CONTRACTED","PARTNER"]},"partnerId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"evidence":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"supportedCargoCategoryIds":{"type":"array","items":{"type":"string","format":"uuid"},"maxItems":100},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","code","mode","equipmentType","serviceWindow","declaredCapacity","provenance","partnerId","evidence","supportedCargoCategoryIds","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'calendars' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"capacityPoolId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"timezone":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"horizon":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"lastVerifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"freshness":{"type":"string","enum":["VERIFIED","ESTIMATED","SIMULATED","UNKNOWN"]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"complete":{"type":"boolean"},"availableWindows":{"type":"array","items":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"maxItems":100},"readyPickupAreaId":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]}},"required":["schemaVersion","serviceId","assetId","capacityPoolId","timezone","horizon","source","lastVerifiedAt","freshness","validUntil","complete","availableWindows","readyPickupAreaId"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'maintenances' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"type":"string","format":"uuid"},"blockedWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"kind":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"status":{"type":"string","enum":["SCHEDULED","IN_PROGRESS","COMPLETED","CANCELLED"]},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"reason":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"}},"required":["schemaVersion","serviceId","assetId","blockedWindow","kind","status","source","reason"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'repositioning-blocks' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"calendarId":{"type":"string","format":"uuid"},"occupiedWindow":{"type":"object","properties":{"startsAt":{"type":"string","format":"date-time"},"endsAt":{"type":"string","format":"date-time"}},"required":["startsAt","endsAt"],"additionalProperties":false},"origin":{"type":"object","properties":{"label":{"type":"string","minLength":1,"pattern":"\\S"},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"]},"city":{"type":"string","minLength":1,"pattern":"\\S"},"lat":{"anyOf":[{"type":"number","minimum":-90,"maximum":90},{"type":"null"}]},"lng":{"anyOf":[{"type":"number","minimum":-180,"maximum":180},{"type":"null"}]}},"required":["label","countryCode","region","city","lat","lng"],"additionalProperties":false},"nextPickup":{"type":"object","properties":{"label":{"type":"string","minLength":1,"pattern":"\\S"},"countryCode":{"type":"string","pattern":"^[A-Z]{2}$"},"region":{"type":["string","null"]},"city":{"type":"string","minLength":1,"pattern":"\\S"},"lat":{"anyOf":[{"type":"number","minimum":-90,"maximum":90},{"type":"null"}]},"lng":{"anyOf":[{"type":"number","minimum":-180,"maximum":180},{"type":"null"}]}},"required":["label","countryCode","region","city","lat","lng"],"additionalProperties":false},"estimatedTravelSeconds":{"type":"integer","exclusiveMinimum":0},"status":{"type":"string","enum":["PLANNED","IN_PROGRESS","COMPLETED","CANCELLED"]},"source":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"reason":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"}},"required":["schemaVersion","serviceId","calendarId","occupiedWindow","origin","nextPickup","estimatedTravelSeconds","status","source","reason"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
when 'asset-capabilities' then s:='{"type":"object","properties":{"schemaVersion":{"type":"string","const":"2.0"},"serviceId":{"type":"string","format":"uuid"},"assetId":{"type":"string","format":"uuid"},"definitionId":{"type":"string","format":"uuid"},"categoryId":{"type":"string","format":"uuid"},"temperatureRange":{"anyOf":[{"type":"object","properties":{"minCelsius":{"type":"number"},"maxCelsius":{"type":"number"}},"required":["minCelsius","maxCelsius"],"additionalProperties":false},{"type":"null"}]},"certifications":{"type":"array","items":{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},"maxItems":100},"evidence":{"anyOf":[{"type":"string","minLength":1,"maxLength":500,"pattern":"\\S"},{"type":"null"}]},"verifiedAt":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"validUntil":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"active":{"type":"boolean"}},"required":["schemaVersion","serviceId","assetId","definitionId","categoryId","temperatureRange","certifications","evidence","verifiedAt","validUntil","active"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}'::json;
end case;
 if not coalesce(extensions.jsonb_matches_schema(s,p_value),false) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
 sid:=(p_value->>'serviceId')::uuid;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,'areas',p_carrier_id,sid,true,null);
 -- Lock the service before examining references; all fleet commands for one service serialize.
 perform 1 from public.carrier_services where id=sid for update;
 h:=private.hash_v2_freight_payload(jsonb_build_object('kind',p_kind,'carrierId',p_carrier_id,'serviceId',null,'id',p_id,'expectedVersion',p_expected_version,'value',p_value));
 perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text||':'||p_member_id::text||':'||p_idempotency_key::text,0));
 select * into receipt from private.v2_catalog_receipts where organization_id=p_organization_id and member_id=p_member_id and idempotency_key=p_idempotency_key;
 if found then if receipt.payload_hash<>h then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='PT409';end if;
 return jsonb_build_object('record',receipt.result,'replay',true);end if;
 if p_id is not null then
  execute format('select version from public.%I where id=$1 and carrier_id=$2 and carrier_service_id=$3 for update',t) into current_version using p_id,p_carrier_id,sid;
  if current_version is null then raise exception 'CATALOG_NOT_FOUND' using errcode='PT404';end if;
  if current_version<>p_expected_version then raise exception 'STALE_DRAFT' using errcode='PT409';end if;
  previous:=private.fleet_record(p_kind,p_id)->'value';
 end if;
 if p_kind in ('assets','capacity-pools') then
  if (p_value->>'mode') is distinct from (select transport_mode from public.carrier_services where id=sid)
  or ((p_value->>'provenance'='PARTNER') is distinct from (p_value->>'partnerId' is not null)) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_value->>'partnerId' is not null and not exists(select 1 from public.fulfilment_partners where id=(p_value->>'partnerId')::uuid and carrier_id=p_carrier_id) then raise exception 'INVALID_PARTNER_SOURCE' using errcode='PT400';end if;
  if p_kind='assets' then
   if (p_value->>'mode'='ROAD') is distinct from (p_value->>'roadVehicle' is not null)
    or (p_value->>'role'='AUXILIARY' and (p_value->>'usefulCapacityKg' is not null or p_value->>'usableVolumeM3' is not null)) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  else
   if (p_value#>>'{serviceWindow,endsAt}')::timestamptz<=(p_value#>>'{serviceWindow,startsAt}')::timestamptz
    or exists(select 1 from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') id where not exists(select 1 from public.cargo_categories where cargo_categories.id=id::uuid and active))
    or jsonb_array_length(p_value->'supportedCargoCategoryIds')<>(select count(distinct id) from jsonb_array_elements_text(p_value->'supportedCargoCategoryIds') id) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end if;
 end if;
 if p_kind='calendars' then
  if num_nonnulls(p_value->>'assetId',p_value->>'capacityPoolId')<>1 then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if not exists(select 1 from pg_timezone_names where name=p_value->>'timezone') then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  start_at:=(p_value#>>'{horizon,startsAt}')::timestamptz;end_at:=(p_value#>>'{horizon,endsAt}')::timestamptz;
  if end_at<=start_at or (p_value->>'lastVerifiedAt')::timestamptz>now()
   or (p_value->>'validUntil')::timestamptz<=(p_value->>'lastVerifiedAt')::timestamptz
   or (p_value->>'freshness'<>'UNKNOWN' and num_nonnulls(p_value->>'lastVerifiedAt',p_value->>'validUntil')<>2) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  for w in select value from jsonb_array_elements(p_value->'availableWindows') loop
   if (w->>'endsAt')::timestamptz<=(w->>'startsAt')::timestamptz or (w->>'startsAt')::timestamptz<start_at or (w->>'endsAt')::timestamptz>end_at then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p_value->'availableWindows') with ordinality a(w,i),jsonb_array_elements(p_value->'availableWindows') with ordinality b(w,i)
   where a.i<b.i and tstzrange((a.w->>'startsAt')::timestamptz,(a.w->>'endsAt')::timestamptz,'[)') && tstzrange((b.w->>'startsAt')::timestamptz,(b.w->>'endsAt')::timestamptz,'[)')) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_value->>'readyPickupAreaId' is not null and not exists(select 1 from public.service_areas where id=(p_value->>'readyPickupAreaId')::uuid and carrier_service_id=sid and area_role='PICKUP' and coverage='INCLUDE' and active) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_id is not null and (previous->>'assetId',previous->>'capacityPoolId') is distinct from (p_value->>'assetId',p_value->>'capacityPoolId') then raise exception 'IMMUTABLE_CAPACITY_SOURCE' using errcode='PT400';end if;
 end if;
 if p_kind in ('calendars','maintenances','asset-capabilities') and p_value->>'assetId' is not null then
  if not exists(select 1 from public.transport_assets where id=(p_value->>'assetId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
 end if;
 if p_kind='calendars' and p_value->>'capacityPoolId' is not null and not exists(select 1 from public.capacity_pools where id=(p_value->>'capacityPoolId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
 if p_kind in ('asset-capabilities','capability-definitions') then
  if not exists(select 1 from public.cargo_categories where id=(p_value->>'categoryId')::uuid and active)
   or (p_value#>>'{temperatureRange,maxCelsius}')::numeric<(p_value#>>'{temperatureRange,minCelsius}')::numeric
   or ((p_value#>>'{temperatureRange,minCelsius}') is null) is distinct from ((p_value#>>'{temperatureRange,maxCelsius}') is null)
   or (p_value->>'validUntil')::timestamptz<=(p_value->>'verifiedAt')::timestamptz
   or (p_value->>'verifiedAt')::timestamptz>now()
   or jsonb_array_length(p_value->'certifications')<>(select count(distinct v) from jsonb_array_elements_text(p_value->'certifications') v)
   then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_kind='capability-definitions' and jsonb_array_length(p_value->'requirements')<>(select count(distinct v) from jsonb_array_elements_text(p_value->'requirements') v) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_id is not null and (previous->>'assetId',previous->>'categoryId',previous->>'definitionId') is distinct from (p_value->>'assetId',p_value->>'categoryId',p_value->>'definitionId') then raise exception 'IMMUTABLE_CAPABILITY_SOURCE' using errcode='PT400';end if;
  if p_kind='asset-capabilities' and not exists(select 1 from public.cargo_capability_definitions d where d.id=(p_value->>'definitionId')::uuid and d.carrier_id=p_carrier_id and d.carrier_service_id=sid and d.active
   and d.cargo_category_id=(p_value->>'categoryId')::uuid and d.temperature_range is not distinct from nullif(p_value->'temperatureRange','null'::jsonb)
   and d.certifications=p_value->'certifications' and d.evidence is not distinct from p_value->>'evidence'
   and d.verified_at is not distinct from (p_value->>'verifiedAt')::timestamptz and d.valid_until is not distinct from (p_value->>'validUntil')::timestamptz)
   then raise exception 'INVALID_CAPABILITY_DEFINITION' using errcode='PT400';end if;
  if p_kind='capability-definitions' and p_id is not null and exists(select 1 from public.asset_cargo_capabilities a join public.capacity_calendars c on c.transport_asset_id=a.transport_asset_id
   join public.capacity_reservations r on r.capacity_calendar_id=c.id where a.definition_id=p_id and r.status in ('HELD','CONFIRMED') and r.ends_at>now()) then raise exception 'FLEET_COMMITMENT_CONFLICT' using errcode='PT409';end if;
 end if;
 if p_kind in ('maintenances','repositioning-blocks') then
  w:=p_value->case when p_kind='maintenances' then 'blockedWindow' else 'occupiedWindow' end;
  start_at:=(w->>'startsAt')::timestamptz;end_at:=(w->>'endsAt')::timestamptz;
  if end_at<=start_at or (p_kind='repositioning-blocks' and (p_value->>'estimatedTravelSeconds')::integer>extract(epoch from end_at-start_at)) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  if p_kind='repositioning-blocks' then
   if not exists(select 1 from public.capacity_calendars where id=(p_value->>'calendarId')::uuid and carrier_id=p_carrier_id and carrier_service_id=sid) then raise exception 'INVALID_FLEET_REFERENCE' using errcode='PT400';end if;
   if ((p_value#>>'{origin,lat}') is null) is distinct from ((p_value#>>'{origin,lng}') is null)
    or ((p_value#>>'{nextPickup,lat}') is null) is distinct from ((p_value#>>'{nextPickup,lng}') is null) then raise exception 'VALIDATION_ERROR' using errcode='PT400';end if;
  end if;
  if p_id is not null and p_value->>(case when p_kind='maintenances' then 'assetId' else 'calendarId' end)
   is distinct from previous->>(case when p_kind='maintenances' then 'assetId' else 'calendarId' end) then raise exception 'IMMUTABLE_BLOCK_SOURCE' using errcode='PT400';end if;
 end if;
 -- Serialize against reservations on the same calendar before changing availability.
 if p_kind='calendars' then cal_id:=p_id;
 elsif p_kind='repositioning-blocks' then cal_id:=(p_value->>'calendarId')::uuid;
 elsif p_kind in ('assets','capacity-pools') then
  select id into cal_id from public.capacity_calendars where (p_kind='assets' and transport_asset_id=p_id) or (p_kind='capacity-pools' and capacity_pool_id=p_id);
 elsif p_kind in ('maintenances','asset-capabilities') then select id into cal_id from public.capacity_calendars where transport_asset_id=(p_value->>'assetId')::uuid;
 end if;
 if cal_id is not null then
  perform 1 from public.capacity_calendars where id=cal_id for update;
  if exists(select 1 from public.capacity_reservations where capacity_calendar_id=cal_id and status in ('HELD','CONFIRMED') and ends_at>now()
    and (p_kind not in ('maintenances','repositioning-blocks') or (p_value->>'status' not in ('COMPLETED','CANCELLED') and tstzrange(starts_at,ends_at,'[)')&&tstzrange(start_at,end_at,'[)')))) then
   raise exception 'FLEET_COMMITMENT_CONFLICT' using errcode='PT409';end if;
 end if;
 case p_kind
when 'capability-definitions' then if p_id is null then insert into public.cargo_capability_definitions(carrier_service_id,cargo_category_id,requirements,max_weight_kg,temperature_range,certifications,evidence,verified_at,valid_until,active,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{categoryId}')::uuid,nullif(p_value#>'{requirements}','null'::jsonb),(p_value#>>'{maxWeightKg}')::numeric,nullif(p_value#>'{temperatureRange}','null'::jsonb),nullif(p_value#>'{certifications}','null'::jsonb),(p_value#>>'{evidence}')::text,(p_value#>>'{verifiedAt}')::timestamptz,(p_value#>>'{validUntil}')::timestamptz,(p_value#>>'{active}')::boolean,true,p_carrier_id) returning id into saved_id;
else update public.cargo_capability_definitions set fleet_managed=true,carrier_service_id=(p_value#>>'{serviceId}')::uuid,cargo_category_id=(p_value#>>'{categoryId}')::uuid,requirements=nullif(p_value#>'{requirements}','null'::jsonb),max_weight_kg=(p_value#>>'{maxWeightKg}')::numeric,temperature_range=nullif(p_value#>'{temperatureRange}','null'::jsonb),certifications=nullif(p_value#>'{certifications}','null'::jsonb),evidence=(p_value#>>'{evidence}')::text,verified_at=(p_value#>>'{verifiedAt}')::timestamptz,valid_until=(p_value#>>'{validUntil}')::timestamptz,active=(p_value#>>'{active}')::boolean where id=p_id returning id into saved_id;end if;
when 'assets' then if p_id is null then insert into public.transport_assets(carrier_service_id,code,mode,equipment_code,asset_role,max_weight_kg,max_volume_m3,operating_status,active,home_depot_id,fulfilment_source,fulfilment_partner_id,evidence,plate,registration_code,registered_at,brand,model,variant,body_type,usable_dimensions,gross_weight_limit_kg,odometer_km,condition_reason,axle_config,fleet_managed,carrier_id) values((p_value#>>'{serviceId}')::uuid,(p_value#>>'{code}')::text,(p_value#>>'{mode}')::text,(p_value#>>'{equipmentType}')::text,case when p_value->>'role'='LOAD_BEARING' then 'CARRIER' else 'ESCORT' end,(p_value#>>'{usefulCapacityKg}')::numeric,(p_value#>>'{usableVolumeM3}')::numeric,(p_value#>>'{operatingStatus}')::text,(p_value->>'operatingStatus'='AVAILABLE'),(p_value#>>'{homeDepotId}')::uuid,(p_value#>>'{provenance}')::text,(p_value#>>'{partnerId}')::uuid,(p_value#>>'{evidence}')::text,(p_value#>>'{roadVehicle,plate}')::text,(p_value#>>'{roadVehicle,registrationCode}')::text,(p_value#>>'{roadVehicle,registeredAt}')::date,(p_value#>>'{roadVehicle,brand}')::text,(p_value#>>'{roadVehicle,model}')::text,(p_value#>>'{roadVehicle,variant}')::text,(p_value#>>'{roadVehicle,bodyType}')::text,nullif(p_value#>'{roadVehicle,usableDimensions}','null'::jsonb),(p_value#>>'{roadVehicle,grossWeightLimitKg}')::numeric,(p_value#>>'{roadVehicle,odometerKm}')::numeric,(p_value#>>'{roadVehicle,conditionReason}')::text,(p_value#>>'{roadVehicle,axleConfig}')::text,true,p_carrier_id) returning id into saved_id;
