revoke all on function private.read_v2_fleet(uuid,uuid,text,uuid,uuid,uuid,integer,integer),private.command_v2_fleet(uuid,uuid,text,uuid,uuid,uuid,uuid,integer,jsonb) from public,anon,authenticated,service_role;
create function private.guard_v2_fleet_reservation() returns trigger language plpgsql security definer set search_path='' as $$
declare c public.capacity_calendars%rowtype;begin
 select * into c from public.capacity_calendars where id=new.capacity_calendar_id for update;
 if (c.fleet_managed or exists(select 1 from public.transport_assets where id=c.transport_asset_id and fleet_managed)
  or exists(select 1 from public.capacity_pools where id=c.capacity_pool_id and fleet_managed)) and new.status in ('HELD','CONFIRMED') then
  if not c.complete or c.provenance_status not in ('VERIFIED','SIMULATED') or c.valid_until is null or c.valid_until<new.ends_at
   or not exists(select 1 from jsonb_array_elements(c.available_windows) w where (w->>'startsAt')::timestamptz<=new.starts_at and (w->>'endsAt')::timestamptz>=new.ends_at)
   or exists(select 1 from public.scheduled_maintenances where transport_asset_id=c.transport_asset_id and status in ('SCHEDULED','IN_PROGRESS') and tstzrange(starts_at,ends_at,'[)')&&tstzrange(new.starts_at,new.ends_at,'[)'))
   or exists(select 1 from public.repositioning_blocks where capacity_calendar_id=c.id and status in ('PLANNED','IN_PROGRESS') and tstzrange(starts_at,ends_at,'[)')&&tstzrange(new.starts_at,new.ends_at,'[)'))
   or exists(select 1 from public.transport_assets where id=c.transport_asset_id and not active)
   or exists(select 1 from public.capacity_pools p where p.id=c.capacity_pool_id and (not active or starts_at is null or ends_at is null or starts_at>new.starts_at or ends_at<new.ends_at or evidence is null))
   then raise exception 'FLEET_COMMITMENT_CONFLICT' using errcode='PT409';end if;
 end if;return new;end;$$;
revoke all on function private.guard_v2_fleet_reservation() from public,anon,authenticated,service_role;
create trigger v2_fleet_reservation_guard before insert or update on public.capacity_reservations for each row execute function private.guard_v2_fleet_reservation();
create or replace function private.read_v2_catalog(p_organization_id uuid,p_member_id uuid,p_kind text,p_carrier_id uuid,
 p_service_id uuid,p_id uuid,p_limit integer,p_offset integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare target record; entry record; result jsonb:='[]'; begin
 if p_kind in ('capability-definitions','assets','capacity-pools','calendars','maintenances','repositioning-blocks','asset-capabilities') then return private.read_v2_fleet(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,p_id,p_limit,p_offset);end if;
 perform private.authorize_v2_catalog(p_organization_id,p_member_id,p_kind,p_carrier_id,p_service_id,false,p_id);
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset not between 0 and 100000 then
 raise exception 'VALIDATION_ERROR' using errcode='PT400'; end if;
 select * into target from private.catalog_target(p_kind,p_organization_id,p_carrier_id,p_service_id);
 for entry in execute format('select id from public.%I where %s and ($1 is null or id=$1) order by created_at,id limit $2 offset $3',target.table_name,target.scope_sql)
 using p_id,p_limit,p_offset loop result:=result||jsonb_build_array(private.catalog_record(p_kind,entry.id)); end loop;
 return result;
end;$$;
